SELECT p.id AS position_id, w.id, w.signal_id, w.execution_key, w.side, w.quantity, w.price_usdt, w.gross_amount_usdt, w.fee_usdt, w.net_amount_usdt, w.cost_basis_usdt, w.realized_pnl_usdt, w.realized_pnl_percent, w.execution_type, w.execution_reason, w.status, w.executed_at, LEFT(w.execution_message,400) AS msg FROM paper_position p JOIN wallet_trade w ON w.symbol=p.symbol AND w.executed_at BETWEEN p.opened_at - INTERVAL 10 SECOND AND p.closed_at + INTERVAL 10 SECOND WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, w.executed_at LIMIT 100